import assert from'node:assert/strict';import{createServer}from'node:http';import{readFile,writeFile,mkdtemp,mkdir}from'node:fs/promises';import{chromium}from'playwright';
const key=process.env.FORMKIT,clean=v=>String(v).replaceAll(key,'[key]'),report={snapshotSha256:'0319bac864adf6686ef9e3e53fd5f2dbcfc25d4b79d5fd5edd64a45b1c2889b5',tests:{},pageErrors:[],requestFailures:[],performanceSamples:0};
const server=createServer(async(req,res)=>{if(req.url==='/'){res.setHeader('Content-Type','text/html');res.end('<!doctype html><html lang="en"><title>FormKit modes</title><link rel="stylesheet" href="/app.css"><style>body{font:16px system-ui;margin:24px}main{width:720px;margin:auto}</style><main><h1>Mode acceptance</h1><div id="app"></div></main><script type="module" src="/app.js"></script></html>');}else if(['/app.js','/app.css'].includes(req.url)){res.setHeader('Content-Type',req.url.endsWith('.css')?'text/css':'text/javascript');res.end(await readFile('../browser'+req.url));}else{res.statusCode=404;res.end();}});await new Promise(r=>server.listen(0,'127.0.0.1',r));let browser,page;
const selected=process.argv[2];async function mount(name,arm){await page.evaluate(({name,arm})=>window.modeApi.mount(name,arm),{name,arm});await page.locator('#app form').waitFor();await page.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));}
const values=()=>page.evaluate(()=>window.modeApi.values());const until=fn=>page.waitForFunction(fn);const paint=()=>page.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));
async function run(id,arm,fn){if(selected&&!selected.split(',').some(part=>id.includes(part)))return;const start=report.pageErrors.length;try{const details=await fn(arm);report.tests[id]??={};report.tests[id][arm]={status:'passed',details,pageErrors:report.pageErrors.slice(start)};}catch(error){report.tests[id]??={};report.tests[id][arm]={status:'failed',error:clean(error.message),pageErrors:report.pageErrors.slice(start),diagnostics:await page.evaluate(()=>({values:window.modeApi.values(),text:document.querySelector('#app').textContent.slice(0,1800),inputs:[...document.querySelectorAll('#app input')].map(el=>({id:el.id,name:el.name,value:el.value,type:el.type})),focus:document.activeElement?.outerHTML.slice(0,600)})).catch(()=>null)};}finally{await page.evaluate(()=>window.modeApi.destroy()).catch(error=>{report.tests[id][arm].cleanupError=clean(error.message)});await paint();await page.evaluate(()=>new Promise(r=>setTimeout(r,70)));report.tests[id][arm].pageErrors=report.pageErrors.slice(start);}console.log(id,arm,JSON.stringify(report.tests[id][arm]));}
async function peers(id,fn){for(let iteration=0;iteration<Number(process.env.MODE_REPETITIONS??1);iteration++)for(const arm of ['adapter','react','vue'])await run(Number(process.env.MODE_REPETITIONS??1)>1?id+'-'+iteration:id,arm,fn)}
try{const temp=await mkdtemp('/tmp/fkmodes-');await mkdir('../browser/config',{recursive:true});await mkdir('../browser/cache',{recursive:true});browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,chromiumSandbox:true,args:['--enable-automation'],env:{...process.env,XDG_CONFIG_HOME:'/workspace/formkit-mode-acceptance/browser/config',XDG_CACHE_HOME:'/workspace/formkit-mode-acceptance/browser/cache',TMPDIR:temp}});report.browserVersion=browser.version();const cdp=await browser.newBrowserCDPSession();report.effectiveArgv=(await cdp.send('Browser.getBrowserCommandLine')).arguments;assert.ok(!report.effectiveArgv.some(x=>['--no-sandbox','--disable-setuid-sandbox'].includes(x)));const context=await browser.newContext({viewport:{width:1100,height:900},locale:'en-US',timezoneId:'UTC'});page=await context.newPage();page.setDefaultTimeout(8000);page.on('pageerror',error=>report.pageErrors.push(clean(error.stack??error.message)));page.on('requestfailed',req=>report.requestFailures.push({origin:new URL(req.url()).origin,error:req.failure()?.errorText}));await page.goto(`http://127.0.0.1:${server.address().port}`);await page.waitForFunction(()=>window.modeApi);await page.evaluate(key=>window.modeApi.setup(key),key);
await peers('pro-autocomplete-multiple-new-max',async arm=>{await mount('autocompleteMultiple',arm);const input=page.getByRole('combobox');await input.fill('Be');await page.getByRole('option',{name:'Beta',exact:true}).click();await until(()=>window.modeApi.values().search?.length===2);assert.deepEqual((await values()).search,['a','b']);assert.equal(await input.isEditable(),false);await page.getByRole('button',{name:'Remove',exact:true}).first().click();await until(()=>window.modeApi.values().search?.length===1);await input.fill('Delta');await input.press('Enter');await until(()=>window.modeApi.values().search?.includes('Delta'));assert.deepEqual((await values()).search,['b','Delta']);return{maxRefused:true,removableSelection:true,newValueCreated:true,dom:await page.evaluate(()=>window.modeApi.describe()),multiple:true,max:await page.evaluate(()=>window.modeApi.props('search',['max','allowNewValues'])),values:await values()};});
await peers('pro-color-format-swatches',async arm=>{await mount('colorFormats',arm);const rgba=page.locator('[data-type="colorpicker"]').first();await rgba.locator('.formkit-hex-field').fill('#00ff0080');await until(()=>window.modeApi.values().rgba?.includes('rgba'));const color=await values();assert.ok(color.rgba.includes('0.5')||color.rgba.includes('0.502'));const swatches=page.locator('[data-type="colorpicker"]').nth(1);await swatches.locator('.formkit-swatch-preview').click();await swatches.locator('.formkit-swatch-canvas').last().click();await until(()=>window.modeApi.values().swatches==='#00FF00');return await values();});
await peers('pro-currency-localized-numeric',async arm=>{await mount('currencyLocale',arm);const input=page.getByLabel('Euro cost',{exact:true});await input.fill('12,50');await input.press('ArrowUp');await until(()=>window.modeApi.values().cost==='12.75');await input.press('Tab');assert.ok((await input.inputValue()).includes('12,75'));assert.ok(!(await input.inputValue()).includes('€'));await input.fill('1000');await input.press('Tab');await paint();const aboveMax=(await values()).cost;await input.fill('-50');await input.press('Tab');await paint();return{boundsObserved:{aboveMax,belowMin:(await values()).cost,props:await page.evaluate(()=>window.modeApi.props('cost',['min','max']))},value:await values(),display:await input.inputValue()};});
await peers('pro-date-panels-zone',async arm=>{await mount('datePanels',arm);await page.getByLabel('Zoned appointment',{exact:true}).click();const data=await page.evaluate(()=>({values:window.modeApi.values(),props:window.modeApi.props('appointment',['timezone','sequence','showMonths']),buttons:[...document.querySelectorAll('[data-type="datepicker"] button')].map(el=>({text:el.textContent,aria:el.getAttribute('aria-label')})).slice(0,16)}));assert.equal(data.props.timezone,'Asia/Kolkata');assert.deepEqual(data.props.sequence,['year','month','day','time']);await page.getByText('2024',{exact:true}).click();await page.waitForFunction(()=>window.modeApi.props('appointment',['panel']).panel==='month');await page.getByText(/^Feb(?:ruary)?$/).click();await page.waitForFunction(()=>window.modeApi.props('appointment',['panel']).panel==='day');const disabled=page.getByRole('gridcell',{name:'February 25, 2024',exact:true});assert.equal(await disabled.getAttribute('aria-disabled'),'true');await page.getByRole('gridcell',{name:'February 29, 2024',exact:true}).first().click();await page.waitForFunction(()=>window.modeApi.props('appointment',['panel']).panel==='time');await page.locator('[data-type="datepicker"] input[type="time"]').fill('15:45');await page.locator('[data-type="datepicker"] input[type="time"]').press('Enter');await until(()=>window.modeApi.values().appointment==='2024-02-29T10:15:00.000Z');return{...data,values:await values(),panel:'time',panelText:await page.locator('[data-type="datepicker"]').textContent(),timeControls:await page.locator('[data-type="datepicker"] input, [data-type="datepicker"] select').evaluateAll(items=>items.map(el=>({tag:el.tagName,type:el.type,cls:el.className,value:el.value})))};});
await peers('pro-data-boolean-attrs',async arm=>{await mount('datePanels',arm);await page.getByLabel('Zoned appointment',{exact:true}).click();await page.getByText('2024',{exact:true}).click();await page.getByText(/^Feb(?:ruary)?$/).click();const enabled=page.getByRole('gridcell',{name:'February 29, 2024',exact:true}).first(),disabled=page.getByRole('gridcell',{name:'February 25, 2024',exact:true});const observed={enabled:await enabled.getAttribute('data-disabled'),disabled:await disabled.getAttribute('data-disabled'),ariaEnabled:await enabled.getAttribute('aria-disabled')};assert.equal(observed.enabled,'false');assert.equal(observed.disabled,'true');return observed;});
await peers('pro-date-wall-time',async arm=>{await mount('dateTimeOnly',arm);const input=page.getByLabel('Wall time',{exact:true});await input.click();assert.equal((await values()).alarm,'08:15');return{values:await values(),timeInputs:await page.locator('[data-type="datepicker"] input').count()};});
await peers('pro-dropdown-slot-max',async arm=>{await mount('dropdownMultiple',arm);await page.getByLabel('Many choices',{exact:true}).click();await page.getByRole('option',{name:'Beta',exact:true}).click();await until(()=>window.modeApi.values().many.length===2);assert.deepEqual((await values()).many,['a','b']);return{values:await values(),checked:await page.locator('[role="option"] input:checked').count()};});
await peers('pro-mask-caret-modes',async arm=>{await mount('maskModes',arm);const result={};for(const mode of ['shift','replace','select']){const input=page.getByLabel('Code '+mode,{exact:true});await input.focus();result[mode]={display:await input.inputValue(),selection:await input.evaluate(el=>[el.selectionStart,el.selectionEnd])};assert.ok(result[mode].display.includes('A1B'));}return{modes:result,values:await values(),typing:'Known official React incremental typing limitation retained; no broad typing pass'};});
await peers('pro-rating-fractional',async arm=>{await mount('ratingFractional',arm);const radio=page.locator('input[type="radio"][data-value="2.5"]');await radio.focus();await radio.press('ArrowRight');await paint();const arrowValue=(await values()).stars;const fraction=page.locator('input[type="radio"][data-value="3.5"]');await fraction.focus();await fraction.press('Space');await until(()=>window.modeApi.values().stars===3.5);return{fractionalInitial:2.5,value:(await values()).stars,arrowValue,arrowLimit:arrowValue===2.5};});
await peers('pro-repeater-drag-controls',async arm=>{await mount('repeaterControls',arm);const first=page.locator('input[name="name"]').first();await first.evaluate(el=>window.savedRow=el);await page.locator('.formkit-down-control').first().click();await until(()=>window.modeApi.values().people[1]?.name==='Ada');assert.equal(await page.locator('input[name="name"]').nth(1).evaluate(el=>el===window.savedRow),true);const rows=page.locator('[data-type="repeater"] .formkit-item');await rows.nth(1).locator('.formkit-drag-handle').hover();await page.mouse.down();await page.mouse.move((await rows.nth(0).boundingBox()).x+30,(await rows.nth(0).boundingBox()).y+10,{steps:15});await page.mouse.up();await until(()=>window.modeApi.values().people?.[0]?.name==='Ada');assert.equal(await page.locator('input[name="name"]').first().evaluate(el=>el===window.savedRow),true);await page.locator('.formkit-insert-control').first().click();await until(()=>window.modeApi.values().people.length===3);await page.locator('.formkit-remove-control').first().click();await until(()=>window.modeApi.values().people.length===2);return{values:await values(),draggable:await page.evaluate(()=>window.modeApi.props('people',['draggable','min','max'])),domDrag:await rows.evaluateAll(items=>items.map(el=>({draggable:el.draggable,cls:el.className}))),dragAttempted:true};});
